//! Config files for individual apps: Ptyxis, fish, VS Code, Firefox, Spotifast, plus Slack colors to
//! copy by hand. Each file starts with a "Generated by Pinta" line so Pinta only
//! ever replaces or removes its own.

pub mod firefox;
pub mod fish;
pub mod ptyxis;
pub mod shell_fade;
pub mod slack;
pub mod spotifast;
pub mod vscode;

use std::fs;
use std::io;
use std::path::Path;

use crate::apply::{ApplyError, io_err, write_atomic};
use crate::color::Color;
use crate::palette::Palette;

const MARKER: &str = "Generated by Pinta";

/// Whether the file at `path` is one Pinta wrote. Missing counts as not.
pub fn is_pintas(path: &Path) -> bool {
    fs::read_to_string(path).is_ok_and(|text| text.lines().take(3).any(|l| l.contains(MARKER)))
}

/// Writes `contents` (which must carry the marker) unless someone else's file is there.
fn write_owned(path: &Path, contents: &str) -> Result<(), ApplyError> {
    debug_assert!(contents.lines().take(3).any(|l| l.contains(MARKER)));
    if path.exists() && !is_pintas(path) {
        return Err(ApplyError::Foreign {
            path: path.to_owned(),
        });
    }
    write_atomic(path, contents)
}

/// Removes the file if it is Pinta's. Returns whether it was.
fn remove_owned(path: &Path) -> Result<bool, ApplyError> {
    if !is_pintas(path) {
        return Ok(false);
    }
    match fs::remove_file(path) {
        Ok(()) => Ok(true),
        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(false),
        Err(e) => Err(io_err(path)(e)),
    }
}

/// The 16 terminal colors, in the layout Gogh (and so Ptyxis's built-in palettes)
/// uses: black, red, green, yellow, blue, magenta, cyan, white, then bright.
pub fn ansi(palette: &Palette) -> [Color; 16] {
    let c = &palette.colors;
    [
        c.surface, c.red, c.green, c.yellow, c.blue, c.pink, c.teal, c.subtext, c.overlay, c.red,
        c.green, c.yellow, c.blue, c.pink, c.teal, c.text,
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn owned_files_are_never_someone_elses() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("x.conf");
        write_owned(&path, "# Generated by Pinta\na\n").unwrap();
        assert!(is_pintas(&path));
        assert!(remove_owned(&path).unwrap());
        assert!(!remove_owned(&path).unwrap());

        fs::write(&path, "mine\n").unwrap();
        assert!(matches!(
            write_owned(&path, "# Generated by Pinta\n"),
            Err(ApplyError::Foreign { .. })
        ));
        assert!(!remove_owned(&path).unwrap());
        assert_eq!(fs::read_to_string(&path).unwrap(), "mine\n");
    }
}
